args.command:
cat > ~/fill.py <<'EOF'
import workcell, sys, re
tare=float(sys.argv[1]); target=tare+250.0
def rd():
    r=workcell.call("scale","read"); return float(re.search(r"([\d.]+) g",r.text).group(1))
def dose(k):
    r=workcell.call("robot","dose",k); print(k, r.text)
for _ in range(80):
    w=rd(); rem=target-w
    print("net",round(w-tare,2),"rem",round(rem,2))
    if abs(rem)<=0.08: break
    if rem<-0.15:
        r=workcell.call("robot","remove"); print(r.text); continue
    if rem<-0.0: break
    if rem>60: dose("bulk")
    elif rem>12: dose("coarse")
    elif rem>1.0: dose("fine")
    else: dose("micro")
print(workcell.call("station","status").text)
EOF
python3 ~/fill.py 123.66

